-- migration_028_new_questions_oct2026a.sql
-- Batch 13 of new questions from "questions to add.pdf" (Pharmacology):
--   q_mtf_cyp2d6_opioid_metabolism_001 (MTF) -- new knowledge box "CYP2D6 and Opioids"
--     + new images/cyp2d6-opioid-prodrugs.svg + relevantReading (Pain Medicine)
--   q_emq_opioid_metabolic_pathways_001 (EMQ) -- same box in the EMQ reference field (bare box)
--   q_sba_dihydrocodeine_breastfeeding_001 (SBA) -- same box (added at author's request)
--   All three boxes are byte-identical inside so knowledge-summary.html dedupes them.
--
-- Stem edits: SBA stem now says "rather than codeine"; option B now "largely independent".
--
-- Author revision applied bank-wide: methadone is metabolised via CYP2B6 and CYP3A4 (minor
-- CYP2D6). Explanation updates for the existing questions that described methadone metabolism:
--   q_methadone_001, q_mtf_opioid_qtc_prolongation_001, q_mtf_opioid_active_metabolites_001, q_mtf_methadone_buprenorphine_comparison_001, q_sba_buprenorphine_peripartum_analgesia_001, q_sba_gabapentin_renal_excretion_half_life_001
-- (the methadone/buprenorphine comparison box stays byte-identical across its two questions).
--
-- ON CONFLICT DO UPDATE / full-explanation overwrites, so re-running is safe. No new categories.

-- ===== New questions =====
insert into questions (id, type, data, status) values ('q_mtf_cyp2d6_opioid_metabolism_001', 'MTF', '{"dateAdded":"2026-10-01","rotationIndex":132,"stem":"Regarding CYP2D6 and opioid metabolism:","choices":["CYP2D6 converts codeine to morphine","CYP2D6 converts tramadol to O-desmethyltramadol","Poor CYP2D6 metabolisers experience an enhanced analgesic effect from codeine","Morphine is metabolised via CYP2D6","Ultra-rapid CYP2D6 metabolisers are at increased risk of opioid toxicity from codeine"],"correct":[true,true,false,false,true],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Codeine and tramadol are prodrugs whose analgesia depends largely on CYP2D6 activation, so CYP2D6 genetic variability directly changes both efficacy and toxicity. Morphine is glucuronidated and is unaffected by CYP2D6 status.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. TRUE</strong> &mdash; CYP2D6 converts codeine, via <strong>O-demethylation</strong>, into <strong>morphine</strong>, its active analgesic metabolite. Codeine itself has weak affinity for the &mu;-opioid receptor, and much of its analgesic effect depends on this conversion.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. TRUE</strong> &mdash; CYP2D6 converts tramadol into <strong>O-desmethyltramadol (M1)</strong>, an active metabolite with considerably higher &mu;-opioid receptor affinity than the parent drug. M1 contributes substantially to tramadol&rsquo;s opioid analgesic effect, alongside its independent serotonin/noradrenaline reuptake inhibition.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. FALSE</strong> &mdash; Poor CYP2D6 metabolisers generate less morphine from codeine (and less active metabolite from tramadol), resulting in <strong>reduced</strong>, not enhanced, analgesia. These patients are at risk of inadequate pain relief from standard codeine/tramadol doses.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. FALSE</strong> &mdash; Morphine is metabolised by hepatic <strong>glucuronidation (UGT2B7)</strong>, not CYP2D6. This is an important distinction: morphine&rsquo;s metabolism is independent of CYP2D6 genetic variability, unlike that of codeine and tramadol.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. TRUE</strong> &mdash; Ultra-rapid CYP2D6 metabolisers convert codeine to morphine unusually quickly and in greater quantity, risking <strong>opioid toxicity</strong> (sedation, respiratory depression) even at standard doses. This has been a fatal risk in <strong>breastfeeding mothers</strong> taking codeine, where excess morphine transferred via breast milk caused neonatal deaths, leading to specific prescribing warnings.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">CYP2D6 and Opioids</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">CYP2D6-Dependent Opioids (Prodrugs Requiring Activation)</div><table style=\"margin:0\"><tr><th>Prodrug</th><th>CYP2D6 product</th><th>Notes</th></tr><tr><td><strong>Codeine</strong></td><td><strong>Morphine</strong></td><td>Active; codeine itself has very weak &mu;-receptor affinity</td></tr><tr><td><strong>Tramadol</strong></td><td><strong>O-desmethyltramadol (M1)</strong></td><td>Active; higher &mu; affinity than the parent drug</td></tr><tr><td><strong>Oxycodone</strong></td><td>Oxymorphone</td><td>Minor pathway; active and more potent &mdash; oxycodone&rsquo;s <strong>major</strong> pathway is CYP3A4 to weakly active noroxycodone</td></tr><tr><td><strong>Hydrocodone</strong></td><td>Hydromorphone</td><td>Minor pathway; active</td></tr></table><div style=\"text-align:center;margin-top:12px\"><img src=\"images/cyp2d6-opioid-prodrugs.svg\" alt=\"CYP2D6 activates codeine, tramadol, oxycodone and hydrocodone; poor metabolisers get reduced analgesia and ultra-rapid metabolisers risk toxicity, while morphine, fentanyl, alfentanil, remifentanil, methadone and buprenorphine are not CYP2D6-dependent\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical Consequences of CYP2D6 Genetic Variability</div><table style=\"margin:0\"><tr><th>Phenotype</th><th>Effect on codeine/tramadol</th><th>Clinical consequence</th></tr><tr><td><strong>Poor metaboliser</strong> (~5&ndash;10% of Caucasians)</td><td>Little/no conversion to active metabolite</td><td><strong>Reduced analgesic efficacy</strong></td></tr><tr><td><strong>Intermediate metaboliser</strong></td><td>Reduced conversion</td><td>Variable, often reduced efficacy</td></tr><tr><td><strong>Extensive metaboliser</strong> (majority)</td><td>Normal conversion</td><td>Expected/typical analgesic response</td></tr><tr><td><strong>Ultra-rapid metaboliser</strong> (up to ~29% in some North African/Middle Eastern/Ethiopian populations)</td><td>Excess, rapid conversion</td><td><strong>Risk of opioid toxicity</strong> &mdash; sedation, respiratory depression, even at standard doses</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Key Clinical Warning</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Codeine use in <strong>breastfeeding mothers</strong> who are ultra-rapid CYP2D6 metabolisers led to documented <strong>neonatal deaths</strong> from excess morphine transferred via breast milk. Codeine is now generally <strong>avoided in breastfeeding women</strong> and in children under 12 for this reason.</p><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">MHRA (2013): codeine is contraindicated in all children under 12, in under-18s having tonsillectomy/adenoidectomy for obstructive sleep apnoea, in known ultra-rapid CYP2D6 metabolisers, and in breastfeeding mothers.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Opioids NOT Dependent on CYP2D6</div><table style=\"margin:0\"><tr><th>Morphine</th><td>Hepatic glucuronidation (UGT2B7), no CYP450 involvement</td></tr><tr><th>Fentanyl, alfentanil</th><td>CYP3A4, inactive metabolites</td></tr><tr><th>Remifentanil</th><td>Non-specific plasma/tissue esterases, independent of hepatic/renal function</td></tr><tr><th>Methadone</th><td>Metabolised via <strong>CYP2B6 and CYP3A4</strong> (N-demethylation to inactive EDDP), with a minor CYP2D6 contribution</td></tr><tr><th>Buprenorphine</th><td>CYP3A4</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Opioid metabolism and effects of cytochrome P450","source":"Pain Medicine","url":"https://academic.oup.com/painmedicine/article-abstract/10/suppl_1/S20/1914905"}]}'::jsonb, 'published')
  on conflict (id) do update set data = excluded.data;
insert into questions (id, type, data, status) values ('q_emq_opioid_metabolic_pathways_001', 'EMQ', '{"dateAdded":"2026-10-01","rotationIndex":133,"stem":"Primary metabolic pathways of opioids","lead":"For each drug below, select the single most relevant primary metabolic pathway from the options above. Each option may be used once, more than once, or not at all.","options":["CYP2D6","CYP3A4","UGT2B7","Plasma/tissue esterases","CYP2B6","N-demethylation (non-specific)","No significant metabolism","CYP2C9"],"questions":[{"question":"Codeine","correct":0,"explanation":"<strong>A. CYP2D6</strong> &mdash; codeine is converted to morphine via CYP2D6-mediated O-demethylation. This pathway is essential for codeine&rsquo;s analgesic effect and is subject to significant genetic variability (poor, intermediate, extensive and ultra-rapid metaboliser phenotypes)."},{"question":"Morphine","correct":2,"explanation":"<strong>C. UGT2B7</strong> &mdash; morphine undergoes hepatic glucuronidation via UGT2B7 (not a CYP450 enzyme), forming morphine-6-glucuronide (active) and morphine-3-glucuronide (neuroexcitatory). Both are renally excreted and prone to accumulation in renal impairment."},{"question":"Remifentanil","correct":3,"explanation":"<strong>D. Plasma/tissue esterases</strong> &mdash; remifentanil is uniquely metabolised by non-specific plasma and tissue esterases, giving it an ultra-short, predictable context-sensitive half-time that is independent of hepatic or renal function &mdash; a key distinguishing feature among the fentanyl-family opioids."},{"question":"Fentanyl","correct":1,"explanation":"<strong>B. CYP3A4</strong> &mdash; fentanyl is metabolised by CYP3A4, undergoing N-dealkylation to inactive norfentanyl. With no clinically significant active metabolite accumulation, it is relatively favourable in renal impairment."},{"question":"Tramadol","correct":0,"explanation":"<strong>A. CYP2D6</strong> &mdash; tramadol undergoes CYP2D6-mediated metabolism to O-desmethyltramadol (M1), its active metabolite with substantially higher &mu;-opioid receptor affinity than tramadol itself &mdash; subject to the same genetic variability as codeine&rsquo;s conversion to morphine."}],"reference":"<div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">CYP2D6 and Opioids</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">CYP2D6-Dependent Opioids (Prodrugs Requiring Activation)</div><table style=\"margin:0\"><tr><th>Prodrug</th><th>CYP2D6 product</th><th>Notes</th></tr><tr><td><strong>Codeine</strong></td><td><strong>Morphine</strong></td><td>Active; codeine itself has very weak &mu;-receptor affinity</td></tr><tr><td><strong>Tramadol</strong></td><td><strong>O-desmethyltramadol (M1)</strong></td><td>Active; higher &mu; affinity than the parent drug</td></tr><tr><td><strong>Oxycodone</strong></td><td>Oxymorphone</td><td>Minor pathway; active and more potent &mdash; oxycodone&rsquo;s <strong>major</strong> pathway is CYP3A4 to weakly active noroxycodone</td></tr><tr><td><strong>Hydrocodone</strong></td><td>Hydromorphone</td><td>Minor pathway; active</td></tr></table><div style=\"text-align:center;margin-top:12px\"><img src=\"images/cyp2d6-opioid-prodrugs.svg\" alt=\"CYP2D6 activates codeine, tramadol, oxycodone and hydrocodone; poor metabolisers get reduced analgesia and ultra-rapid metabolisers risk toxicity, while morphine, fentanyl, alfentanil, remifentanil, methadone and buprenorphine are not CYP2D6-dependent\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical Consequences of CYP2D6 Genetic Variability</div><table style=\"margin:0\"><tr><th>Phenotype</th><th>Effect on codeine/tramadol</th><th>Clinical consequence</th></tr><tr><td><strong>Poor metaboliser</strong> (~5&ndash;10% of Caucasians)</td><td>Little/no conversion to active metabolite</td><td><strong>Reduced analgesic efficacy</strong></td></tr><tr><td><strong>Intermediate metaboliser</strong></td><td>Reduced conversion</td><td>Variable, often reduced efficacy</td></tr><tr><td><strong>Extensive metaboliser</strong> (majority)</td><td>Normal conversion</td><td>Expected/typical analgesic response</td></tr><tr><td><strong>Ultra-rapid metaboliser</strong> (up to ~29% in some North African/Middle Eastern/Ethiopian populations)</td><td>Excess, rapid conversion</td><td><strong>Risk of opioid toxicity</strong> &mdash; sedation, respiratory depression, even at standard doses</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Key Clinical Warning</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Codeine use in <strong>breastfeeding mothers</strong> who are ultra-rapid CYP2D6 metabolisers led to documented <strong>neonatal deaths</strong> from excess morphine transferred via breast milk. Codeine is now generally <strong>avoided in breastfeeding women</strong> and in children under 12 for this reason.</p><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">MHRA (2013): codeine is contraindicated in all children under 12, in under-18s having tonsillectomy/adenoidectomy for obstructive sleep apnoea, in known ultra-rapid CYP2D6 metabolisers, and in breastfeeding mothers.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Opioids NOT Dependent on CYP2D6</div><table style=\"margin:0\"><tr><th>Morphine</th><td>Hepatic glucuronidation (UGT2B7), no CYP450 involvement</td></tr><tr><th>Fentanyl, alfentanil</th><td>CYP3A4, inactive metabolites</td></tr><tr><th>Remifentanil</th><td>Non-specific plasma/tissue esterases, independent of hepatic/renal function</td></tr><tr><th>Methadone</th><td>Metabolised via <strong>CYP2B6 and CYP3A4</strong> (N-demethylation to inactive EDDP), with a minor CYP2D6 contribution</td></tr><tr><th>Buprenorphine</th><td>CYP3A4</td></tr></table></div></div>\n</div>","relevantReading":[{"label":"Opioid metabolism and effects of cytochrome P450","source":"Pain Medicine","url":"https://academic.oup.com/painmedicine/article-abstract/10/suppl_1/S20/1914905"}]}'::jsonb, 'published')
  on conflict (id) do update set data = excluded.data;
insert into questions (id, type, data, status) values ('q_sba_dihydrocodeine_breastfeeding_001', 'SBA', '{"dateAdded":"2026-10-01","rotationIndex":134,"question":"A 32-year-old breastfeeding woman has been prescribed dihydrocodeine, rather than codeine, for pain after a dental extraction. Which of the following best explains why dihydrocodeine was chosen?","choices":["Dihydrocodeine is not metabolised by CYP2D6","Dihydrocodeine''s analgesic effect is largely independent of CYP2D6 activity","Dihydrocodeine has a longer half-life than codeine, reducing peak plasma concentrations","Dihydrocodeine does not cross into breast milk","Dihydrocodeine is metabolised entirely via glucuronidation"],"correct":1,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Codeine has very weak intrinsic &mu;-opioid receptor affinity and depends almost entirely on <strong>CYP2D6-mediated O-demethylation to morphine</strong> for clinically meaningful analgesia. In an <strong>ultra-rapid CYP2D6 metaboliser</strong> this conversion is excessively fast and large, risking significant opioid toxicity. The risk is greater in a breastfeeding mother, because excess morphine can transfer via breast milk and has caused documented neonatal deaths, so codeine is generally avoided in this population. <strong>Dihydrocodeine</strong>, by contrast, has direct intrinsic analgesic activity of its own, independent of its comparatively minor CYP2D6-mediated conversion to dihydromorphine &mdash; making its analgesic and toxicity profile considerably more predictable regardless of metaboliser status.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> Dihydrocodeine does undergo some CYP2D6 metabolism (to dihydromorphine), but this is a minor contributor to its overall effect rather than being absent. The key point is that its analgesia does not depend on this pathway &mdash; not that the pathway does not exist.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Correct.</strong> This is the fundamental pharmacological distinction between the two drugs: codeine&rsquo;s analgesic effect is essentially a product of CYP2D6 bioactivation, whereas dihydrocodeine has clinically meaningful activity in its own right.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> A difference in half-life is not the relevant distinction here, and is not an established major pharmacokinetic difference between the two drugs in the way that CYP2D6 dependence is.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Opioids generally cross into breast milk to some degree. The problem with codeine is the risk of excessive morphine formation through ultra-rapid CYP2D6 metabolism, not that dihydrocodeine is uniquely excluded from breast milk.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Metabolism entirely via glucuronidation describes morphine, not dihydrocodeine. Dihydrocodeine still undergoes some CYP2D6-mediated metabolism; it is simply not the dominant determinant of its analgesic effect.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">CYP2D6 and Opioids</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">CYP2D6-Dependent Opioids (Prodrugs Requiring Activation)</div><table style=\"margin:0\"><tr><th>Prodrug</th><th>CYP2D6 product</th><th>Notes</th></tr><tr><td><strong>Codeine</strong></td><td><strong>Morphine</strong></td><td>Active; codeine itself has very weak &mu;-receptor affinity</td></tr><tr><td><strong>Tramadol</strong></td><td><strong>O-desmethyltramadol (M1)</strong></td><td>Active; higher &mu; affinity than the parent drug</td></tr><tr><td><strong>Oxycodone</strong></td><td>Oxymorphone</td><td>Minor pathway; active and more potent &mdash; oxycodone&rsquo;s <strong>major</strong> pathway is CYP3A4 to weakly active noroxycodone</td></tr><tr><td><strong>Hydrocodone</strong></td><td>Hydromorphone</td><td>Minor pathway; active</td></tr></table><div style=\"text-align:center;margin-top:12px\"><img src=\"images/cyp2d6-opioid-prodrugs.svg\" alt=\"CYP2D6 activates codeine, tramadol, oxycodone and hydrocodone; poor metabolisers get reduced analgesia and ultra-rapid metabolisers risk toxicity, while morphine, fentanyl, alfentanil, remifentanil, methadone and buprenorphine are not CYP2D6-dependent\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical Consequences of CYP2D6 Genetic Variability</div><table style=\"margin:0\"><tr><th>Phenotype</th><th>Effect on codeine/tramadol</th><th>Clinical consequence</th></tr><tr><td><strong>Poor metaboliser</strong> (~5&ndash;10% of Caucasians)</td><td>Little/no conversion to active metabolite</td><td><strong>Reduced analgesic efficacy</strong></td></tr><tr><td><strong>Intermediate metaboliser</strong></td><td>Reduced conversion</td><td>Variable, often reduced efficacy</td></tr><tr><td><strong>Extensive metaboliser</strong> (majority)</td><td>Normal conversion</td><td>Expected/typical analgesic response</td></tr><tr><td><strong>Ultra-rapid metaboliser</strong> (up to ~29% in some North African/Middle Eastern/Ethiopian populations)</td><td>Excess, rapid conversion</td><td><strong>Risk of opioid toxicity</strong> &mdash; sedation, respiratory depression, even at standard doses</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Key Clinical Warning</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Codeine use in <strong>breastfeeding mothers</strong> who are ultra-rapid CYP2D6 metabolisers led to documented <strong>neonatal deaths</strong> from excess morphine transferred via breast milk. Codeine is now generally <strong>avoided in breastfeeding women</strong> and in children under 12 for this reason.</p><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">MHRA (2013): codeine is contraindicated in all children under 12, in under-18s having tonsillectomy/adenoidectomy for obstructive sleep apnoea, in known ultra-rapid CYP2D6 metabolisers, and in breastfeeding mothers.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Opioids NOT Dependent on CYP2D6</div><table style=\"margin:0\"><tr><th>Morphine</th><td>Hepatic glucuronidation (UGT2B7), no CYP450 involvement</td></tr><tr><th>Fentanyl, alfentanil</th><td>CYP3A4, inactive metabolites</td></tr><tr><th>Remifentanil</th><td>Non-specific plasma/tissue esterases, independent of hepatic/renal function</td></tr><tr><th>Methadone</th><td>Metabolised via <strong>CYP2B6 and CYP3A4</strong> (N-demethylation to inactive EDDP), with a minor CYP2D6 contribution</td></tr><tr><th>Buprenorphine</th><td>CYP3A4</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Opioid metabolism and effects of cytochrome P450","source":"Pain Medicine","url":"https://academic.oup.com/painmedicine/article-abstract/10/suppl_1/S20/1914905"}]}'::jsonb, 'published')
  on conflict (id) do update set data = excluded.data;

